/* =====================================================================
   Ebanist — Noutăți (D-184)
   ---------------------------------------------------------------------
   Ce s-a schimbat la fiecare versiune, în cuvintele utilizatorului, în
   cele 7 limbi ale aplicației. Modul pur: nu atinge DOM-ul, nu citește
   starea. index.html doar pune în foaia „Noutăți” textul de la render().

   Regula (în CLAUDE.md): o versiune care schimbă ce vede sau ce poate
   face utilizatorul adaugă aici o intrare, în toate cele 7 limbi, în
   aceeași comandă cu CHANGELOG.md. Telemetria, testele și reparațiile
   interne nu intră. Intrările mai vechi sunt articolele din blog.

   Format: RELEASES[i] = { v, date: "AAAA-LL-ZZ", t: { <limbă>: { title, items[] } } }
           cea mai nouă prima.
   ===================================================================== */
(function (global) {
  "use strict";

  var LANGS = ["en", "ro", "it", "fr", "de", "pl", "es"];

  var UI = {
    en: { title: "What's new", version: "Version", older: "Older versions and the full story:", blog: "Ebanist blog" },
    ro: { title: "Noutăți", version: "Versiunea", older: "Versiuni mai vechi și povestea completă:", blog: "blogul Ebanist" },
    it: { title: "Novità", version: "Versione", older: "Versioni precedenti e la storia completa:", blog: "blog di Ebanist" },
    fr: { title: "Nouveautés", version: "Version", older: "Versions précédentes et l'histoire complète :", blog: "blog Ebanist" },
    de: { title: "Neuigkeiten", version: "Version", older: "Frühere Versionen und die ganze Geschichte:", blog: "Ebanist-Blog" },
    pl: { title: "Nowości", version: "Wersja", older: "Starsze wersje i pełna historia:", blog: "blog Ebanist" },
    es: { title: "Novedades", version: "Versión", older: "Versiones anteriores y la historia completa:", blog: "blog de Ebanist" }
  };

  var RELEASES = [
    { v: "5.117.0", date: "2026-11-27", t: {
      en: { title: "Five tabs instead of seven", items: ["The bottom bar now has five tabs: Projects, Survey, Design, Parts and Documents. Kitchen sits next to the Generator in Design, and the cutting layout next to the list in Parts, with a switch at the top of the page.", "Nothing was removed and nothing moved to a different place in the project; only the way you reach it changed. Labels no longer touch on small phones."] },
      ro: { title: "Cinci file în loc de șapte", items: ["Bara de jos are acum cinci file: Proiecte, Releveu, Proiectează, Piese și Documente. Bucătăria stă lângă Generator în „Proiectează”, iar debitarea lângă listă în „Piese”, cu un comutator sus în pagină.", "Nu s-a scos nimic și nimic nu s-a mutat în alt loc din proiect; s-a schimbat doar drumul până la ele. Etichetele nu se mai ating pe telefoane mici."] },
      it: { title: "Cinque schede invece di sette", items: ["La barra in basso ha ora cinque schede: Progetti, Rilievo, Progetta, Pezzi e Documenti. La cucina sta accanto al Generatore in «Progetta», e il taglio accanto alla lista in «Pezzi», con un selettore in alto nella pagina.", "Non è stato tolto niente e niente è cambiato di posto nel progetto; è cambiata solo la strada per arrivarci. Le etichette non si toccano più sui telefoni piccoli."] },
      fr: { title: "Cinq onglets au lieu de sept", items: ["La barre du bas compte maintenant cinq onglets : Projets, Relevé, Concevoir, Pièces et Documents. La cuisine se trouve à côté du Générateur dans « Concevoir », et la découpe à côté de la liste dans « Pièces », avec un sélecteur en haut de la page.", "Rien n'a été retiré et rien n'a changé de place dans le projet ; seul le chemin pour y accéder a changé. Les libellés ne se touchent plus sur les petits téléphones."] },
      de: { title: "Fünf Reiter statt sieben", items: ["Die untere Leiste hat jetzt fünf Reiter: Projekte, Aufmaß, Entwerfen, Teile und Dokumente. Die Küche steht beim Konfigurator unter „Entwerfen“, die Aufteilung bei der Liste unter „Teile“, mit einem Umschalter oben auf der Seite.", "Nichts wurde entfernt und nichts im Projekt verschoben; nur der Weg dorthin hat sich geändert. Die Beschriftungen berühren sich auf kleinen Telefonen nicht mehr."] },
      pl: { title: "Pięć kart zamiast siedmiu", items: ["Dolny pasek ma teraz pięć kart: Projekty, Pomiar, Projektuj, Części i Dokumenty. Kuchnia jest obok Konfiguratora w „Projektuj”, a rozkrój obok listy w „Części”, z przełącznikiem u góry strony.", "Nic nie usunięto i nic w projekcie nie zmieniło miejsca; zmieniła się tylko droga do tych widoków. Podpisy nie stykają się już na małych telefonach."] },
      es: { title: "Cinco pestañas en lugar de siete", items: ["La barra inferior tiene ahora cinco pestañas: Proyectos, Medición, Diseñar, Piezas y Documentos. La cocina está junto al Configurador en «Diseñar», y el corte junto a la lista en «Piezas», con un selector en la parte superior de la página.", "No se quitó nada y nada cambió de lugar en el proyecto; solo cambió el camino para llegar. Las etiquetas ya no se tocan en teléfonos pequeños."] }
    } },
    { v: "5.116.1", date: "2026-11-27", t: {
      en: { title: "Correct Romanian wording", items: ["In Romanian, the page with what changed in each update is now called “Noutăți”, the correct word, instead of “Novități”."] },
      ro: { title: "Cuvânt corect în română", items: ["Pagina cu ce s-a schimbat la fiecare actualizare se numește acum „Noutăți”, cuvântul corect, în loc de „Novități”."] },
      it: { title: "Termine corretto in rumeno", items: ["In rumeno, la pagina con le modifiche di ogni aggiornamento ora si chiama «Noutăți», il termine corretto, invece di «Novități»."] },
      fr: { title: "Terme roumain corrigé", items: ["En roumain, la page des changements de chaque mise à jour s'appelle désormais « Noutăți », le terme correct, au lieu de « Novități »."] },
      de: { title: "Korrekter rumänischer Begriff", items: ["Auf Rumänisch heißt die Seite mit den Änderungen jedes Updates jetzt „Noutăți“, der richtige Begriff, statt „Novități“."] },
      pl: { title: "Poprawne rumuńskie słowo", items: ["Po rumuńsku strona ze zmianami w każdej aktualizacji nazywa się teraz „Noutăți”, czyli poprawnie, zamiast „Novități”."] },
      es: { title: "Término rumano corregido", items: ["En rumano, la página con los cambios de cada actualización se llama ahora «Noutăți», el término correcto, en lugar de «Novități»."] }
    } },
    { v: "5.116.0", date: "2026-11-26", t: {
      en: { title: "Projects with a picture, and easier to tap", items: ["Each project card now shows a small drawing of the project and icons next to pieces, units, area and edging.", "On the phone, swipe a project card to the left to duplicate or delete it. Delete asks for confirmation and can be undone.", "Small buttons are now easy to hit (at least 44 px of touch area). In Summary, the export actions are a tidy list with arrows, like the Settings of your phone."] },
      ro: { title: "Proiecte cu poză și mai ușor de atins", items: ["Fiecare card de proiect arată acum un mic desen al proiectului și iconițe lângă piese, corpuri, suprafață și cant.", "Pe telefon, glisează cardul unui proiect spre stânga ca să-l duplici sau să-l ștergi. Ștergerea cere confirmare și se poate anula.", "Butoanele mici se nimeresc acum ușor (cel puțin 44 px de zonă de atingere). În Rezumat, acțiunile de export sunt o listă ordonată cu săgeți, ca în Setările telefonului."] },
      it: { title: "Progetti con immagine e più facili da toccare", items: ["Ogni scheda progetto mostra ora un piccolo disegno del progetto e icone accanto a pezzi, corpi, superficie e bordo.", "Sul telefono, scorri una scheda progetto verso sinistra per duplicarla o eliminarla. L'eliminazione chiede conferma e si può annullare.", "I pulsanti piccoli sono ora facili da colpire (almeno 44 px di area di tocco). In Riepilogo, le azioni di esportazione sono un elenco ordinato con frecce, come nelle Impostazioni del telefono."] },
      fr: { title: "Des projets avec une image, plus faciles à toucher", items: ["Chaque carte de projet affiche maintenant un petit dessin du projet et des icônes à côté des pièces, caissons, surface et chant.", "Sur téléphone, faites glisser une carte de projet vers la gauche pour la dupliquer ou la supprimer. La suppression demande confirmation et peut être annulée.", "Les petits boutons sont maintenant faciles à toucher (au moins 44 px de zone tactile). Dans Résumé, les actions d'export forment une liste ordonnée avec des flèches, comme dans les Réglages du téléphone."] },
      de: { title: "Projekte mit Bild, leichter zu treffen", items: ["Jede Projektkarte zeigt jetzt eine kleine Zeichnung des Projekts und Symbole bei Teilen, Korpussen, Fläche und Kante.", "Auf dem Smartphone die Projektkarte nach links wischen, um sie zu duplizieren oder zu löschen. Das Löschen fragt nach und lässt sich rückgängig machen.", "Kleine Schaltflächen lassen sich jetzt leicht treffen (mindestens 44 px Tippfläche). In der Übersicht sind die Export-Aktionen eine aufgeräumte Liste mit Pfeilen, wie in den Einstellungen des Telefons."] },
      pl: { title: "Projekty z obrazkiem i łatwiejsze do dotknięcia", items: ["Każda karta projektu pokazuje teraz mały rysunek projektu i ikony przy częściach, korpusach, powierzchni i okleinie.", "Na telefonie przesuń kartę projektu w lewo, aby go zduplikować lub usunąć. Usunięcie wymaga potwierdzenia i można je cofnąć.", "Małe przyciski łatwo teraz trafić (co najmniej 44 px pola dotyku). W Podsumowaniu akcje eksportu to uporządkowana lista ze strzałkami, jak w Ustawieniach telefonu."] },
      es: { title: "Proyectos con imagen y más fáciles de tocar", items: ["Cada tarjeta de proyecto muestra ahora un pequeño dibujo del proyecto e iconos junto a piezas, cuerpos, superficie y canto.", "En el teléfono, desliza una tarjeta de proyecto hacia la izquierda para duplicarla o eliminarla. Eliminar pide confirmación y se puede deshacer.", "Los botones pequeños son ahora fáciles de acertar (al menos 44 px de zona táctil). En Resumen, las acciones de exportación son una lista ordenada con flechas, como en los Ajustes del teléfono."] }
    } },
    { v: "5.115.1", date: "2026-11-26", t: {
      en: { title: "Step-by-step assembly for every kind of unit", items: ["The new step-by-step assembly sheet now covers tables, beds (including the lift-up storage bed), desks, round and oval shelves, appliance niches, worktops, wall panelling and contours, not only cabinets.", "Each of them gets the same layout: phases, the parts used by each step with their numbers, the hardware you need, and warnings for two people or fixing to the wall.", "Desks have their own steps: frame, cable holes, top, drawer unit and keyboard shelf."] },
      ro: { title: "Montaj pas cu pas pentru orice tip de corp", items: ["Fișa de montaj nouă, pas cu pas, acoperă acum și mesele, paturile (inclusiv patul cu ladă ridicabilă), birourile, rafturile rotunde și ovale, nișele de aparate, blaturile, lambriurile și conturul, nu doar corpurile de dulap.", "Fiecare are aceeași formă: faze, piesele fiecărui pas cu numerele lor, feroneria de care ai nevoie și avertismente pentru două persoane sau fixare în perete.", "Birourile au pași proprii: cadru, treceri de cablu, blat, corp cu sertare și raft de tastatură."] },
      it: { title: "Montaggio passo dopo passo per ogni tipo di mobile", items: ["La nuova scheda di montaggio passo dopo passo copre ora anche tavoli, letti (compreso il letto con contenitore sollevabile), scrivanie, ripiani tondi e ovali, nicchie per elettrodomestici, piani di lavoro, boiserie e sagome, non solo armadi e mobili.", "Ognuno ha lo stesso schema: fasi, i pezzi di ogni passo con i loro numeri, la ferramenta che serve e avvisi per due persone o fissaggio al muro.", "Le scrivanie hanno passi propri: telaio, passacavi, piano, blocco cassetti e ripiano tastiera."] },
      fr: { title: "Montage pas à pas pour tous les types de meubles", items: ["La nouvelle fiche de montage pas à pas couvre maintenant aussi les tables, les lits (y compris le lit à coffre relevable), les bureaux, les étagères rondes et ovales, les niches d'appareils, les plans de travail, les lambris et les contours, pas seulement les caissons.", "Chacun suit la même présentation : phases, pièces de chaque étape avec leurs numéros, quincaillerie nécessaire et avertissements pour deux personnes ou fixation au mur.", "Les bureaux ont leurs propres étapes : cadre, passe-câbles, plateau, caisson à tiroirs et tablette clavier."] },
      de: { title: "Montage Schritt für Schritt für jede Möbelart", items: ["Das neue Montageblatt Schritt für Schritt deckt jetzt auch Tische, Betten (auch das Bett mit Hubstauraum), Schreibtische, runde und ovale Regale, Gerätenischen, Arbeitsplatten, Wandverkleidungen und Konturen ab, nicht nur Schränke.", "Alle haben dasselbe Schema: Phasen, die Teile jedes Schritts mit ihren Nummern, die nötigen Beschläge und Hinweise für zwei Personen oder die Wandbefestigung.", "Schreibtische haben eigene Schritte: Rahmen, Kabeldurchlässe, Platte, Schubladenelement und Tastaturbrett."] },
      pl: { title: "Montaż krok po kroku dla każdego rodzaju mebla", items: ["Nowa instrukcja montażu krok po kroku obejmuje teraz także stoły, łóżka (w tym łóżko z podnoszonym pojemnikiem), biurka, okrągłe i owalne półki, wnęki na sprzęt, blaty, boazerie i kontury, nie tylko szafy.", "Każdy ma ten sam układ: fazy, części każdego kroku z numerami, potrzebne okucia i ostrzeżenia dla dwóch osób lub mocowania do ściany.", "Biurka mają własne kroki: rama, przepusty kablowe, blat, korpus z szufladami i półka na klawiaturę."] },
      es: { title: "Montaje paso a paso para cada tipo de mueble", items: ["La nueva ficha de montaje paso a paso cubre ahora también mesas, camas (incluida la cama con arcón elevable), escritorios, estantes redondos y ovalados, nichos de electrodomésticos, encimeras, revestimientos de pared y contornos, no solo armarios.", "Todos siguen el mismo esquema: fases, las piezas de cada paso con sus números, los herrajes necesarios y avisos para dos personas o fijación a la pared.", "Los escritorios tienen sus propios pasos: bastidor, pasacables, tablero, bloque de cajones y bandeja del teclado."] }
    } },
    { v: "5.115.0", date: "2026-11-26", t: {
      en: { title: "Assembly sheet, step by step", items: ["The assembly sheet now groups the steps into phases (preparation, pre-assembly, carcass, placing, inside, drawers, doors, finishing) with a heading for each.", "Every step shows which parts it uses, with the numbers from the parts list, and which hardware you need for it, with quantities.", "Small pictograms warn when two people are needed, when the unit must be fixed to the wall, and when not to force a joint. Step pictures are larger, and the back panel and standing the unit up now have one too."] },
      ro: { title: "Fișa de montaj, pas cu pas", items: ["Fișa de montaj grupează acum pașii în faze (pregătire, premontaj, carcasă, așezare, interior, sertare, uși, finisaj), fiecare cu titlul ei.", "Fiecare pas arată ce piese folosește, cu numerele din lista de piese, și ce feronerie îi trebuie, cu cantități.", "Pictograme mici avertizează când sunt necesare două persoane, când corpul trebuie fixat în perete și când să nu forțezi o îmbinare. Imaginile pașilor sunt mai mari, iar spatele și ridicarea corpului au acum și ele una."] },
      it: { title: "Scheda di montaggio, passo dopo passo", items: ["La scheda di montaggio raggruppa ora i passi in fasi (preparazione, premontaggio, cassa, posizionamento, interno, cassetti, ante, finitura), ognuna con il suo titolo.", "Ogni passo mostra quali pezzi usa, con i numeri della lista dei pezzi, e quale ferramenta serve, con le quantità.", "Piccoli pittogrammi avvisano quando servono due persone, quando il mobile va fissato al muro e quando non forzare un giunto. Le immagini dei passi sono più grandi, e ora ce l'hanno anche lo schienale e il sollevamento del mobile."] },
      fr: { title: "Fiche de montage, pas à pas", items: ["La fiche de montage regroupe désormais les étapes en phases (préparation, prémontage, caisson, mise en place, intérieur, tiroirs, portes, finitions), chacune avec son titre.", "Chaque étape indique quelles pièces elle utilise, avec les numéros de la liste des pièces, et quelle quincaillerie il faut, avec les quantités.", "De petits pictogrammes signalent quand deux personnes sont nécessaires, quand le meuble doit être fixé au mur et quand ne pas forcer un assemblage. Les images des étapes sont plus grandes, et le fond et la mise debout en ont maintenant une aussi."] },
      de: { title: "Montageblatt, Schritt für Schritt", items: ["Das Montageblatt gliedert die Schritte jetzt in Phasen (Vorbereitung, Vormontage, Korpus, Aufstellen, Innenraum, Schubladen, Türen, Finish), jede mit eigener Überschrift.", "Jeder Schritt zeigt, welche Teile er braucht, mit den Nummern aus der Teileliste, und welche Beschläge dafür nötig sind, mit Mengen.", "Kleine Piktogramme warnen, wenn zwei Personen nötig sind, wenn das Möbel an der Wand befestigt werden muss und wenn eine Verbindung nicht mit Gewalt gefügt werden darf. Die Bilder sind größer, und auch Rückwand und Aufstellen haben jetzt eines."] },
      pl: { title: "Instrukcja montażu, krok po kroku", items: ["Instrukcja montażu grupuje teraz kroki w fazy (przygotowanie, wstępny montaż, korpus, ustawienie, wnętrze, szuflady, drzwi, wykończenie), każda z własnym tytułem.", "Każdy krok pokazuje, jakich części używa, z numerami z listy części, i jakich okuć potrzebuje, z ilościami.", "Małe piktogramy ostrzegają, gdy potrzebne są dwie osoby, gdy mebel trzeba przymocować do ściany i gdy nie wolno forsować połączenia. Obrazki kroków są większe, a tył i stawianie mebla też mają już swój."] },
      es: { title: "Ficha de montaje, paso a paso", items: ["La ficha de montaje agrupa ahora los pasos en fases (preparación, premontaje, cuerpo, colocación, interior, cajones, puertas, acabado), cada una con su título.", "Cada paso muestra qué piezas usa, con los números de la lista de piezas, y qué herrajes necesita, con cantidades.", "Pequeños pictogramas avisan cuando hacen falta dos personas, cuando el mueble debe fijarse a la pared y cuando no forzar una unión. Las imágenes de los pasos son más grandes, y ahora también las tienen el fondo y levantar el mueble."] }
    } },
    { v: "5.114.0", date: "2026-11-26", t: {
      en: { title: "Easier to read and to follow", items: ["Phone: the bottom bar fits all seven tabs without labels touching, and the 3D toolbar fades at the edge to show it scrolls.", "Each project card now says what to do next: add the first unit, check the list, tick off the remaining parts, or open the assembly sheet. It only takes you there; it changes nothing.", "The CSV button in Summary now says “Share CSV”, so it is no longer confused with the other “Share” buttons."] },
      ro: { title: "Mai ușor de citit și de urmărit", items: ["Telefon: bara de jos încape cu toate cele șapte file fără ca etichetele să se atingă, iar bara 3D se estompează la margine ca să se vadă că defilează.", "Fiecare card de proiect spune acum ce urmează: adaugă primul mobilier, verifică lista, bifează piesele rămase sau deschide fișa de montaj. Doar te duce acolo, nu schimbă nimic.", "Butonul CSV din Rezumat se numește acum „Trimite CSV”, ca să nu fie confundat cu alte butoane „Trimite”."] },
      it: { title: "Più facile da leggere e da seguire", items: ["Telefono: la barra in basso contiene tutte e sette le schede senza etichette sovrapposte, e la barra 3D sfuma al bordo per mostrare che scorre.", "Ogni scheda progetto dice ora cosa fare dopo: aggiungi il primo mobile, controlla la distinta, spunta i pezzi rimasti o apri la scheda di montaggio. Ti porta solo lì, non cambia nulla.", "Il pulsante CSV nel Riepilogo ora si chiama «Condividi CSV», per non confonderlo con altri pulsanti «Condividi»."] },
      fr: { title: "Plus facile à lire et à suivre", items: ["Téléphone : la barre du bas contient les sept onglets sans que les libellés se touchent, et la barre 3D s'estompe au bord pour montrer qu'elle défile.", "Chaque carte de projet indique maintenant la suite : ajouter le premier meuble, vérifier la liste, cocher les pièces restantes ou ouvrir la fiche de montage. Elle vous y conduit seulement, sans rien modifier.", "Le bouton CSV du Résumé s'appelle désormais « Partager le CSV », pour ne plus être confondu avec d'autres boutons « Partager »."] },
      de: { title: "Leichter zu lesen und zu verfolgen", items: ["Smartphone: Die untere Leiste fasst alle sieben Reiter, ohne dass sich die Beschriftungen berühren, und die 3D-Leiste blendet am Rand aus, um zu zeigen, dass sie scrollt.", "Jede Projektkarte sagt jetzt, was als Nächstes ansteht: erstes Möbel hinzufügen, Liste prüfen, restliche Teile abhaken oder das Montageblatt öffnen. Sie führt nur dorthin und ändert nichts.", "Die CSV-Schaltfläche in der Übersicht heißt jetzt „CSV teilen“, damit sie nicht mit anderen „Teilen“-Schaltflächen verwechselt wird."] },
      pl: { title: "Łatwiej czytać i śledzić", items: ["Telefon: dolny pasek mieści wszystkie siedem kart bez stykających się podpisów, a pasek 3D zanika przy krawędzi, pokazując, że się przewija.", "Każda karta projektu mówi teraz, co dalej: dodaj pierwszy mebel, sprawdź listę, odhacz pozostałe części albo otwórz instrukcję montażu. Tylko tam przenosi, niczego nie zmienia.", "Przycisk CSV w Podsumowaniu nazywa się teraz „Udostępnij CSV”, żeby nie mylić go z innymi przyciskami „Udostępnij”."] },
      es: { title: "Más fácil de leer y de seguir", items: ["Teléfono: la barra inferior cabe con las siete pestañas sin que las etiquetas se toquen, y la barra 3D se desvanece en el borde para indicar que se desplaza.", "Cada tarjeta de proyecto indica ahora qué sigue: añadir el primer mueble, revisar la lista, marcar las piezas restantes o abrir la ficha de montaje. Solo te lleva allí, no cambia nada.", "El botón CSV del Resumen se llama ahora «Compartir CSV», para no confundirlo con otros botones «Compartir»."] }
    } },
    { v: "5.113.4", date: "2026-11-27", t: {
      en: { title: "Easier to tap on touch screens", items: ["Header buttons, the close “X” on sheets and the small icon buttons now have a touch area of at least 44 px on phones and tablets, without looking bigger."] },
      ro: { title: "Butoane mai ușor de atins pe ecran tactil", items: ["Butoanele din antet, „X”-ul foilor și butoanele mici cu iconiță au acum zonă de atingere de cel puțin 44 px pe telefon și tabletă, fără să se vadă mai mari."] },
      it: { title: "Pulsanti più facili da toccare sul touch", items: ["I pulsanti dell'intestazione, la «X» dei fogli e i piccoli pulsanti con icona hanno ora un'area di tocco di almeno 44 px su telefono e tablet, senza apparire più grandi."] },
      fr: { title: "Boutons plus faciles à toucher sur écran tactile", items: ["Les boutons de l'en-tête, la « X » des feuilles et les petits boutons à icône ont maintenant une zone de toucher d'au moins 44 px sur téléphone et tablette, sans paraître plus grands."] },
      de: { title: "Tasten am Touchscreen leichter zu treffen", items: ["Tasten in der Kopfzeile, das „X“ der Blätter und die kleinen Symboltasten haben am Handy und Tablet jetzt eine Touchfläche von mindestens 44 px, ohne größer zu wirken."] },
      pl: { title: "Łatwiej trafić w przyciski na ekranie dotykowym", items: ["Przyciski w nagłówku, „X” arkuszy i małe przyciski z ikoną mają teraz obszar dotyku co najmniej 44 px na telefonie i tablecie, bez powiększania wyglądu."] },
      es: { title: "Botones más fáciles de tocar en pantalla táctil", items: ["Los botones de la cabecera, la «X» de las hojas y los pequeños botones con icono tienen ahora un área táctil de al menos 44 px en móvil y tableta, sin verse más grandes."] }
    } },
    { v: "5.113.3", date: "2026-11-26", t: {
      en: { title: "The 3D view clears the toolbar on phones", items: ["In the builder on a phone, the furniture no longer sits under the row of 3D buttons: the view leaves room at the top. Documents, photos and clips are unchanged."] },
      ro: { title: "Vederea 3D lasă loc barei de butoane pe telefon", items: ["În Generator, pe telefon, mobila nu mai stă sub rândul de butoane 3D: imaginea lasă loc sus. Documentele, pozele și clipurile rămân la fel."] },
      it: { title: "La vista 3D lascia spazio alla barra su telefono", items: ["Nel Generatore, su telefono, il mobile non sta più sotto la riga dei pulsanti 3D: la vista lascia spazio in alto. Documenti, foto e clip restano uguali."] },
      fr: { title: "La vue 3D laisse place à la barre sur téléphone", items: ["Dans le Générateur, sur téléphone, le meuble ne passe plus sous la rangée de boutons 3D : la vue laisse de la place en haut. Documents, photos et clips restent identiques."] },
      de: { title: "Die 3D-Ansicht lässt am Handy Platz für die Leiste", items: ["Im Konfigurator liegt das Möbel am Handy nicht mehr unter der Reihe der 3D-Tasten: die Ansicht lässt oben Platz. Dokumente, Fotos und Clips bleiben unverändert."] },
      pl: { title: "Widok 3D zostawia miejsce na pasek w telefonie", items: ["W Konfiguratorze na telefonie mebel nie leży już pod rzędem przycisków 3D: widok zostawia miejsce u góry. Dokumenty, zdjęcia i klipy bez zmian."] },
      es: { title: "La vista 3D deja sitio a la barra en el móvil", items: ["En el Configurador, en el móvil, el mueble ya no queda bajo la fila de botones 3D: la vista deja espacio arriba. Documentos, fotos y clips no cambian."] }
    } },
    { v: "5.113.2", date: "2026-11-26", t: {
      en: { title: "Cleaner bottom bar on phones", items: ["The seven tabs in the bottom bar no longer touch each other on narrow screens: smaller labels, and a long word is shortened with “…” instead of running into its neighbour."] },
      ro: { title: "Bara de jos pe telefon, mai curată", items: ["Cele șapte taburi din bara de jos nu se mai ating pe ecranele înguste: etichete mai mici, iar un cuvânt prea lung se scurtează cu „…” în loc să se suprapună peste vecin."] },
      it: { title: "Barra in basso più pulita sul telefono", items: ["I sette tab della barra in basso non si toccano più sugli schermi stretti: etichette più piccole e, se una parola è troppo lunga, si accorcia con «…» invece di finire addosso alla vicina."] },
      fr: { title: "Barre du bas plus propre sur téléphone", items: ["Les sept onglets de la barre du bas ne se touchent plus sur les écrans étroits : libellés plus petits, et un mot trop long est raccourci par « … » au lieu de chevaucher son voisin."] },
      de: { title: "Aufgeräumtere untere Leiste am Handy", items: ["Die sieben Tabs der unteren Leiste berühren sich auf schmalen Bildschirmen nicht mehr: kleinere Beschriftungen, und ein zu langes Wort wird mit „…“ gekürzt, statt in das Nachbarwort zu laufen."] },
      pl: { title: "Czytelniejszy dolny pasek w telefonie", items: ["Siedem kart w dolnym pasku nie nachodzi już na siebie na wąskich ekranach: mniejsze etykiety, a zbyt długie słowo jest skracane znakiem „…” zamiast wchodzić na sąsiednie."] },
      es: { title: "Barra inferior más limpia en el móvil", items: ["Las siete pestañas de la barra inferior ya no se tocan en pantallas estrechas: etiquetas más pequeñas y, si una palabra es demasiado larga, se acorta con «…» en lugar de pisar a su vecina."] }
    } },
    { v: "5.113.1", date: "2026-11-25", t: {
      en: { title: "Five more tips in Help", items: ["“Tips & Tricks” grows by five: experiment on a duplicated project, red checks with fixes, hardware suggestions that never apply themselves, “Print everything”, and what the free version can do."] },
      ro: { title: "Încă cinci sfaturi în Ajutor", items: ["„Tips & Tricks” crește cu cinci: experimentează pe un proiect duplicat, controalele roșii cu soluții, sugestiile de feronerie care nu se aplică singure, „Tipărește tot” și ce poate versiunea gratuită."] },
      it: { title: "Altri cinque consigli nella Guida", items: ["«Tips & Tricks» cresce di cinque: sperimenta su un progetto duplicato, controlli rossi con soluzioni, suggerimenti di ferramenta che non si applicano da soli, «Stampa tutto» e cosa fa la versione gratuita."] },
      fr: { title: "Cinq astuces de plus dans l'Aide", items: ["« Trucs et astuces » s'enrichit de cinq : expérimenter sur un projet dupliqué, contrôles rouges avec solutions, suggestions de quincaillerie jamais appliquées seules, « Tout imprimer » et ce que permet la version gratuite."] },
      de: { title: "Fünf weitere Tipps in der Hilfe", items: ["„Tipps und Tricks“ wächst um fünf: am duplizierten Projekt testen, rote Prüfungen mit Lösungen, Beschlagvorschläge, die sich nie selbst anwenden, „Alles drucken“ und was die kostenlose Version kann."] },
      pl: { title: "Pięć kolejnych porad w Pomocy", items: ["„Porady i triki” rosną o pięć: eksperymenty na zduplikowanym projekcie, czerwone kontrole z rozwiązaniami, podpowiedzi okuć, które nie stosują się same, „Drukuj wszystko” i co potrafi wersja darmowa."] },
      es: { title: "Cinco consejos más en la Ayuda", items: ["«Trucos y consejos» crece en cinco: experimentar en un proyecto duplicado, controles rojos con soluciones, sugerencias de herrajes que nunca se aplican solas, «Imprimir todo» y qué permite la versión gratuita."] }
    } },
    { v: "5.113.0", date: "2026-11-25", t: {
      en: { title: "Tips & Tricks in Help", items: ["New topic “Tips & Tricks” at the end of Help (also on the website): five small tricks that save time, such as duplicating a unit, checking the parts in the exploded view, the part sheet with its QR code, and the cut size minus edge band."] },
      ro: { title: "Tips & Tricks în Ajutor", items: ["Subiect nou, „Tips & Tricks”, la sfârșitul Ajutorului (și pe site): cinci trucuri mici care economisesc timp, de exemplu duplicarea unui corp, verificarea pieselor în vederea explodată, fișa piesei cu codul QR și cota de tăiere minus cantul."] },
      it: { title: "Tips & Tricks nella Guida", items: ["Nuovo argomento «Tips & Tricks» in fondo alla Guida (anche sul sito): cinque piccoli trucchi che fanno risparmiare tempo, come duplicare un modulo, controllare i pezzi nella vista esplosa, la scheda pezzo con il QR e la quota di taglio meno il bordo."] },
      fr: { title: "Trucs et astuces dans l'Aide", items: ["Nouveau sujet « Trucs et astuces » à la fin de l'Aide (aussi sur le site) : cinq petites astuces qui font gagner du temps, comme dupliquer un module, vérifier les pièces en vue éclatée, la fiche pièce avec son QR et la cote de coupe moins le chant."] },
      de: { title: "Tipps und Tricks in der Hilfe", items: ["Neues Thema „Tipps und Tricks“ am Ende der Hilfe (auch auf der Website): fünf kleine Tricks, die Zeit sparen, etwa einen Korpus duplizieren, die Teile in der Explosionsansicht prüfen, das Teileblatt mit QR-Code und das Zuschnittmaß minus Kante."] },
      pl: { title: "Porady i triki w Pomocy", items: ["Nowy temat „Porady i triki” na końcu Pomocy (także na stronie): pięć drobnych trików oszczędzających czas, na przykład duplikowanie modułu, sprawdzanie części w widoku rozstrzelonym, karta części z kodem QR i wymiar cięcia pomniejszony o okleinę."] },
      es: { title: "Trucos y consejos en la Ayuda", items: ["Nuevo tema «Trucos y consejos» al final de la Ayuda (también en la web): cinco pequeños trucos que ahorran tiempo, como duplicar un módulo, revisar las piezas en la vista explosionada, la ficha de la pieza con su QR y la medida de corte menos el canto."] }
    } },
    { v: "5.112.0", date: "2026-11-25", t: {
      en: { title: "Kitchen on adjustable feet, with a clip-on plinth", items: ["New kitchen setting “Plinth”: adjustable feet + clip-on plinth. The units stand on four round feet, visible in 3D behind the plinth.", "The plinth clips are added to the bill of materials and to the assembly sheet. The cut list does not change."] },
      ro: { title: "Bucătărie pe picioare reglabile, cu soclu clipsat", items: ["Setare nouă în Bucătărie, „Soclu”: picioare reglabile + soclu cu clipsuri. Corpurile stau pe patru picioare rotunde, vizibile în 3D în spatele soclului.", "Clipsurile soclului intră în deviz și în fișa de montaj. Distinta pieselor nu se schimbă."] },
      it: { title: "Cucina su piedini regolabili, con zoccolo a clip", items: ["Nuova impostazione in Cucina, «Zoccolo»: piedini regolabili + zoccolo a clip. I moduli poggiano su quattro piedini rotondi, visibili in 3D dietro lo zoccolo.", "Le clip dello zoccolo entrano nel preventivo e nella scheda di montaggio. La distinta dei pezzi non cambia."] },
      fr: { title: "Cuisine sur pieds réglables, avec socle à clips", items: ["Nouveau réglage en Cuisine, « Socle » : pieds réglables + socle à clips. Les meubles reposent sur quatre pieds ronds, visibles en 3D derrière le socle.", "Les clips du socle sont ajoutés au devis et à la fiche de montage. La liste de débit ne change pas."] },
      de: { title: "Küche auf Stellfüßen, mit Clip-Sockel", items: ["Neue Küchen-Einstellung „Sockel“: Stellfüße + Sockel mit Clips. Die Schränke stehen auf vier runden Füßen, in 3D hinter dem Sockel sichtbar.", "Die Sockelclips kommen in die Stückliste der Beschläge und ins Montageblatt. Der Zuschnitt ändert sich nicht."] },
      pl: { title: "Kuchnia na nóżkach regulowanych, z cokołem na klipsy", items: ["Nowe ustawienie w Kuchni, „Cokół”: nóżki regulowane + cokół na klipsy. Szafki stoją na czterech okrągłych nóżkach, widocznych w 3D za cokołem.", "Klipsy cokołu trafiają do wyceny i do karty montażu. Lista cięcia się nie zmienia."] },
      es: { title: "Cocina sobre patas regulables, con zócalo de clips", items: ["Nuevo ajuste en Cocina, «Zócalo»: patas regulables + zócalo con clips. Los muebles se apoyan en cuatro patas redondas, visibles en 3D detrás del zócalo.", "Los clips del zócalo entran en el presupuesto y en la hoja de montaje. El despiece no cambia."] }
    } },
    { v: "5.111.0", date: "2026-11-25", t: {
      en: { title: "Narrow pull-out baskets in the kitchen", items: ["The pull-out base unit now starts at 150 mm and has a new field, “Pull-out from the catalogue”: 150 mm wire baskets, or Peka Pinello Cargo at 200 and 300 mm. The baskets show in 3D; they are bought, not cut.", "If a unit is too narrow for its drawer, “Apply” now stops with a clear message instead of building the cabinet with no drawer and no front."] },
      ro: { title: "Extractibile înguste cu coșuri la bucătărie", items: ["Baza extractibilă începe acum de la 150 mm și are un câmp nou, „Extractibil din catalog”: coșuri de sârmă de 150 mm sau Peka Pinello Cargo la 200 și 300 mm. Coșurile se văd în 3D; se cumpără, nu se taie.", "Dacă un corp e prea îngust pentru sertarul lui, „Aplică” se oprește acum cu un mesaj clar, în loc să construiască corpul fără sertar și fără front."] },
      it: { title: "Estraibili stretti con cestelli in cucina", items: ["Il base estraibile parte ora da 150 mm e ha un nuovo campo, «Estraibile dal catalogo»: cestelli a filo da 150 mm o Peka Pinello Cargo a 200 e 300 mm. I cestelli si vedono in 3D; si comprano, non si tagliano.", "Se un modulo è troppo stretto per il suo cassetto, «Applica» si ferma ora con un messaggio chiaro invece di costruire il mobile senza cassetto e senza frontale."] },
      fr: { title: "Coulissants étroits à paniers dans la cuisine", items: ["Le meuble bas coulissant commence maintenant à 150 mm et a un nouveau champ, « Coulissant du catalogue » : paniers filaires de 150 mm ou Peka Pinello Cargo en 200 et 300 mm. Les paniers s'affichent en 3D ; ils s'achètent, ils ne se découpent pas.", "Si un meuble est trop étroit pour son tiroir, « Appliquer » s'arrête maintenant avec un message clair au lieu de construire le meuble sans tiroir ni façade."] },
      de: { title: "Schmale Auszüge mit Körben in der Küche", items: ["Der Auszugsunterschrank beginnt jetzt bei 150 mm und hat ein neues Feld „Auszug aus dem Katalog“: Drahtkörbe mit 150 mm oder Peka Pinello Cargo mit 200 und 300 mm. Die Körbe erscheinen in 3D; sie werden gekauft, nicht zugeschnitten.", "Ist ein Korpus für seine Schublade zu schmal, stoppt „Anwenden“ jetzt mit einer klaren Meldung, statt den Korpus ohne Schublade und ohne Front zu bauen."] },
      pl: { title: "Wąskie wysuwy z koszami w kuchni", items: ["Szafka dolna z wysuwem zaczyna się teraz od 150 mm i ma nowe pole „Wysuw z katalogu”: kosze druciane 150 mm albo Peka Pinello Cargo 200 i 300 mm. Kosze widać w 3D; kupuje się je, nie tnie.", "Jeśli korpus jest za wąski na swoją szufladę, „Zastosuj” zatrzymuje się teraz z czytelnym komunikatem, zamiast budować korpus bez szuflady i frontu."] },
      es: { title: "Extraíbles estrechos con cestas en la cocina", items: ["El mueble bajo extraíble empieza ahora en 150 mm y tiene un campo nuevo, «Extraíble del catálogo»: cestas de alambre de 150 mm o Peka Pinello Cargo en 200 y 300 mm. Las cestas se ven en 3D; se compran, no se cortan.", "Si un mueble es demasiado estrecho para su cajón, «Aplicar» se detiene ahora con un mensaje claro en lugar de construir el mueble sin cajón ni frente."] }
    } },
    { v: "5.110.0", date: "2026-11-25", t: {
      en: { title: "Print everything, and cut-outs on the spindle moulder sheet", items: ["A new “Print everything” button in “Sheets per station” prints the whole project file in one go, in workshop order (Pro).", "Cut-outs, such as sockets in the panelling support, now appear on the spindle moulder sheet and on the label route, not only on the label."] },
      ro: { title: "Tipărește tot și decupajele la toupie", items: ["Un buton nou, „Tipărește tot”, în „Foi pe postazione”: tipărește dosarul întreg al proiectului dintr-o dată, în ordinea atelierului (Pro).", "Decupajele, de exemplu prizele din suportul lambriului, apar acum pe foaia toupie și în traseul de pe etichetă, nu doar pe etichetă."] },
      it: { title: "Stampa tutto e scassi alla toupie", items: ["Un nuovo pulsante «Stampa tutto» in «Fogli per postazione» stampa l'intero dossier del progetto in una volta, nell'ordine del laboratorio (Pro).", "Gli scassi, per esempio le prese nel supporto della boiserie, compaiono ora sul foglio toupie e nel percorso dell'etichetta, non solo sull'etichetta."] },
      fr: { title: "Tout imprimer et découpes à la toupie", items: ["Un nouveau bouton « Tout imprimer » dans « Fiches par poste » imprime tout le dossier du projet d'un coup, dans l'ordre de l'atelier (Pro).", "Les découpes, par exemple les prises dans le support du lambris, apparaissent maintenant sur la fiche toupie et dans le parcours de l'étiquette, pas seulement sur l'étiquette."] },
      de: { title: "Alles drucken und Ausschnitte an der Fräse", items: ["Eine neue Schaltfläche „Alles drucken“ in „Blätter je Station“ druckt die ganze Projektmappe auf einmal, in Werkstattreihenfolge (Pro).", "Ausschnitte, etwa Steckdosen im Träger der Wandverkleidung, erscheinen jetzt auf dem Fräsblatt und im Weg auf dem Etikett, nicht nur auf dem Etikett."] },
      pl: { title: "Drukuj wszystko i wycięcia przy frezarce", items: ["Nowy przycisk „Drukuj wszystko” w „Karty na stanowisko” drukuje całą teczkę projektu naraz, w kolejności warsztatu (Pro).", "Wycięcia, na przykład gniazdka w podłożu okładziny, pojawiają się teraz na karcie frezarki i w trasie na etykiecie, nie tylko na etykiecie."] },
      es: { title: "Imprimir todo y recortes en el tupí", items: ["Un botón nuevo «Imprimir todo» en «Hojas por puesto» imprime todo el dossier del proyecto de una vez, en el orden del taller (Pro).", "Los recortes, por ejemplo las tomas en el soporte del revestimiento, aparecen ahora en la hoja de tupí y en el recorrido de la etiqueta, no solo en la etiqueta."] }
    } },
    { v: "5.109.0", date: "2026-11-25", t: {
      en: { title: "Routing sheet", items: ["New in “Sheets per station”: a one-page routing sheet per project. Each station that has work gets a row to tick, date and initial when done. Print it first."] },
      ro: { title: "Fișa de parcurs", items: ["Nou în „Foi pe postazione”: fișa de parcurs, o pagină pe proiect. Fiecare postazione cu lucru primește un rând în care bifează, datează și paraphează când termină. Se tipărește prima."] },
      it: { title: "Scheda di percorso", items: ["Novità in «Fogli per postazione»: la scheda di percorso, una pagina per progetto. Ogni postazione con del lavoro ha una riga dove spunta, data e firma quando ha finito. Si stampa per prima."] },
      fr: { title: "Fiche de parcours", items: ["Nouveau dans « Fiches par poste » : la fiche de parcours, une page par projet. Chaque poste qui a du travail a une ligne où cocher, dater et parapher à la fin. À imprimer en premier."] },
      de: { title: "Laufzettel", items: ["Neu in „Blätter je Station“: der Laufzettel, eine Seite pro Projekt. Jede Station mit Arbeit hat eine Zeile zum Abhaken, Datieren und Abzeichnen. Zuerst drucken."] },
      pl: { title: "Karta przebiegu", items: ["Nowość w „Karty na stanowisko”: karta przebiegu, jedna strona na projekt. Każde stanowisko z pracą ma wiersz do zaznaczenia, datowania i parafowania po zakończeniu. Drukuj ją pierwszą."] },
      es: { title: "Hoja de ruta", items: ["Novedad en «Hojas por puesto»: la hoja de ruta, una página por proyecto. Cada puesto con trabajo tiene una fila para marcar, fechar y firmar al terminar. Se imprime primero."] }
    } },
    { v: "5.108.0", date: "2026-11-24", t: {
      en: { title: "Sheets per station", items: ["One new button, “Sheets per station”, groups the documents by workshop station in the order the piece travels: order list, cutting plan and labels, spindle moulder sheet, edge sheet, drilling sheets (one A4 per piece with holes), assembly sheet, handover record. No account or scanning needed.", "The same rX code now appears on the label, the cutting plan and the sheets, so a piece can be found on paper.", "The legal pages now say “production documents”."] },
      ro: { title: "Foi pe postazione", items: ["Un buton nou, „Foi pe postazione”, grupează documentele pe locurile de lucru ale atelierului, în ordinea în care trece piesa: lista de comandă, planul de tăiere și etichetele, foaia toupie, foaia cantului, fișele de găurire (câte o A4 pe piesă cu găuri), fișa de montaj, procesul-verbal de predare. Nu cere cont și nici scanare.", "Același cod rX apare acum pe etichetă, pe planul de tăiere și pe foi, ca să găsești o piesă pe hârtie.", "Paginile juridice spun acum „documente de fabricație”."] },
      it: { title: "Fogli per postazione", items: ["Un nuovo pulsante, «Fogli per postazione», raggruppa i documenti per postazione del laboratorio, nell'ordine in cui passa il pezzo: lista ordine, piano di taglio ed etichette, foglio toupie, foglio bordo, schede di foratura (una A4 per pezzo con fori), scheda di montaggio, verbale di consegna. Non servono account né scansione.", "Lo stesso codice rX compare ora sull'etichetta, sul piano di taglio e sui fogli, così un pezzo si ritrova su carta.", "Le pagine legali ora dicono «documenti di produzione»."] },
      fr: { title: "Fiches par poste", items: ["Un nouveau bouton, « Fiches par poste », regroupe les documents par poste de l'atelier, dans l'ordre où la pièce circule : liste de commande, plan de coupe et étiquettes, fiche toupie, feuille des chants, fiches de perçage (une A4 par pièce percée), fiche de montage, procès-verbal de livraison. Ni compte ni scan.", "Le même code rX apparaît maintenant sur l'étiquette, le plan de coupe et les fiches, pour retrouver une pièce sur papier.", "Les pages légales disent maintenant « documents de fabrication »."] },
      de: { title: "Blätter je Station", items: ["Eine neue Schaltfläche, „Blätter je Station“, ordnet die Unterlagen nach Werkstattstation in der Reihenfolge, in der das Teil läuft: Bestellliste, Zuschnittplan und Etiketten, Fräsblatt, Kantenblatt, Bohrblätter (ein A4 pro Teil mit Bohrungen), Montageblatt, Übergabeprotokoll. Weder Konto noch Scan nötig.", "Derselbe Code rX steht jetzt auf Etikett, Zuschnittplan und Blättern, damit man ein Teil auf Papier wiederfindet.", "Die Rechtsseiten sagen jetzt „Fertigungsunterlagen“."] },
      pl: { title: "Karty na stanowisko", items: ["Nowy przycisk „Karty na stanowisko” grupuje dokumenty według stanowisk warsztatu, w kolejności, w jakiej element przechodzi: lista zamówienia, plan cięcia i etykiety, karta frezarki, arkusz okleiny, karty wiercenia (jedna A4 na element z otworami), karta montażu, protokół odbioru. Bez konta i skanowania.", "Ten sam kod rX jest teraz na etykiecie, planie cięcia i kartach, by znaleźć element na papierze.", "Strony prawne mówią teraz „dokumenty produkcyjne”."] },
      es: { title: "Hojas por puesto", items: ["Un botón nuevo, «Hojas por puesto», agrupa los documentos por puesto del taller, en el orden en que pasa la pieza: lista de pedido, plano de corte y etiquetas, hoja de tupí, hoja de cantos, fichas de taladrado (una A4 por pieza con taladros), hoja de montaje, acta de entrega. Sin cuenta ni escaneo.", "El mismo código rX aparece ahora en la etiqueta, el plano de corte y las hojas, para encontrar una pieza en papel.", "Las páginas legales ahora dicen «documentos de fabricación»."] }
    } },
    { v: "5.107.0", date: "2026-11-24", t: {
      en: { title: "Labels and workshop stations", items: ["Each label now shows the piece's route through the workshop, for example Saw › Edge › Drill › Assy, and a letter under the QR code: P (piece sheet, no account), E (order in Atelier) or T (the piece data as text).", "Stations now match the first workshop: spindle moulder and drilling are added; CNC and paint shop stay for later.", "The documents are now called “production documents” (before: workshop documents).", "If the project changed after the Atelier order, you are told that the order QR codes are not printed."] },
      ro: { title: "Etichete și postazioni de atelier", items: ["Fiecare etichetă arată acum traseul piesei prin atelier, de exemplu Tăiere › Cant › Găurire › Montaj, și o literă sub codul QR: P (fișa piesei, fără cont), E (comanda din Atelier) sau T (datele piesei ca text).", "Postazioni se potrivesc cu primul atelier: s-au adăugat freza de banc și găurirea; CNC și vopsitoria rămân pentru mai târziu.", "Documentele se numesc acum „documente de fabricație” (înainte: documente de atelier).", "Dacă proiectul s-a schimbat după comanda din Atelier, ți se spune că QR-urile de comandă nu se tipăresc."] },
      it: { title: "Etichette e postazioni del laboratorio", items: ["Ogni etichetta mostra ora il percorso del pezzo in laboratorio, per esempio Sez › Bord › Fori › Mont, e una lettera sotto il QR: P (scheda del pezzo, senza account), E (ordine in Atelier) o T (i dati del pezzo come testo).", "Le postazioni ora corrispondono al primo laboratorio: aggiunte toupie e foratura; CNC e verniciatura restano per dopo.", "I documenti ora si chiamano «documenti di produzione» (prima: documenti di laboratorio).", "Se il progetto è cambiato dopo l'ordine in Atelier, ti viene detto che i QR d'ordine non si stampano."] },
      fr: { title: "Étiquettes et postes d'atelier", items: ["Chaque étiquette montre maintenant le parcours de la pièce dans l'atelier, par exemple Scie › Chant › Perç. › Mont., et une lettre sous le QR : P (fiche de la pièce, sans compte), E (commande dans Atelier) ou T (les données de la pièce en texte).", "Les postes correspondent au premier atelier : toupie et perçage ajoutés ; CNC et peinture restent pour plus tard.", "Les documents s'appellent maintenant « documents de fabrication » (avant : documents d'atelier).", "Si le projet a changé après la commande dans Atelier, on vous dit que les QR de commande ne sont pas imprimés."] },
      de: { title: "Etiketten und Werkstatt-Stationen", items: ["Jedes Etikett zeigt jetzt den Weg des Teils durch die Werkstatt, zum Beispiel Säge › Kante › Bohren › Mont., und einen Buchstaben unter dem QR-Code: P (Teileblatt, ohne Konto), E (Auftrag in Atelier) oder T (die Teiledaten als Text).", "Die Stationen passen jetzt zur ersten Werkstatt: Tischfräse und Bohren sind neu; CNC und Lackiererei bleiben für später.", "Die Unterlagen heißen jetzt „Fertigungsunterlagen“ (vorher: Werkstattunterlagen).", "Wurde das Projekt nach dem Auftrag in Atelier geändert, wird gemeldet, dass die Auftrags-QR-Codes nicht gedruckt werden."] },
      pl: { title: "Etykiety i stanowiska warsztatu", items: ["Każda etykieta pokazuje teraz drogę elementu przez warsztat, na przykład Cięcie › Okl. › Wiercenie › Mont., oraz literę pod kodem QR: P (karta elementu, bez konta), E (zamówienie w Atelier) lub T (dane elementu jako tekst).", "Stanowiska pasują do pierwszego warsztatu: dodano frezarkę dolnowrzecionową i wiercenie; CNC i lakiernia zostają na później.", "Dokumenty nazywają się teraz „dokumenty produkcyjne” (wcześniej: dokumenty warsztatowe).", "Jeśli projekt zmienił się po zamówieniu w Atelier, dowiesz się, że kody QR zamówienia nie są drukowane."] },
      es: { title: "Etiquetas y puestos del taller", items: ["Cada etiqueta muestra ahora el recorrido de la pieza por el taller, por ejemplo Corte › Tupí › Canto › Taladro › Montaje, y una letra bajo el QR: P (ficha de la pieza, sin cuenta), E (pedido en Atelier) o T (los datos de la pieza como texto).", "Los puestos coinciden con el primer taller: se añaden tupí y taladrado; CNC y pintura quedan para más adelante.", "Los documentos ahora se llaman «documentos de fabricación» (antes: documentos de taller).", "Si el proyecto cambió después del pedido en Atelier, se te avisa de que los QR de pedido no se imprimen."] }
    } },
    { v: "5.106.0", date: "2026-11-23", t: {
      en: { title: "Account: you are told what it gives you", items: ["The Pro screen now says: already paid? Sign in with your account and Pro turns on by itself. If it doesn't, “Check again from the account” looks for it.", "The Account window and the Welcome screen explain that the account brings your projects, catalog and stock to every device."] },
      ro: { title: "Contul: afli ce îți aduce", items: ["Ecranul Pro spune acum: ai plătit deja? Autentifică-te cu contul și Pro se activează singur. Dacă nu se întâmplă, „Verifică din nou din cont” îl caută.", "Fereastra Cont și ecranul de bun venit explică faptul că și contul aduce proiectele, catalogul și stocul pe orice dispozitiv."] },
      it: { title: "Account: ti diciamo cosa ti dà", items: ["La schermata Pro ora dice: hai già pagato? Accedi con il tuo account e il Pro si attiva da solo. Se non succede, «Controlla di nuovo dall'account» lo cerca.", "La finestra Account e la schermata di benvenuto spiegano che l'account porta progetti, catalogo e magazzino su ogni dispositivo."] },
      fr: { title: "Compte : on vous dit ce qu'il apporte", items: ["L'écran Pro dit maintenant : déjà payé ? Connectez-vous avec votre compte et le Pro s'active tout seul. Sinon, « Vérifier à nouveau depuis le compte » le cherche.", "La fenêtre Compte et l'écran de bienvenue expliquent que le compte apporte projets, catalogue et stock sur chaque appareil."] },
      de: { title: "Konto: Sie erfahren, was es bringt", items: ["Der Pro-Bildschirm sagt jetzt: schon bezahlt? Melden Sie sich mit Ihrem Konto an, und Pro schaltet sich von selbst ein. Falls nicht, sucht „Vom Konto aus erneut prüfen“ danach.", "Das Konto-Fenster und der Willkommensbildschirm erklären, dass das Konto Projekte, Katalog und Bestand auf jedes Gerät bringt."] },
      pl: { title: "Konto: dowiesz się, co daje", items: ["Ekran Pro mówi teraz: już zapłaciłeś? Zaloguj się na konto, a Pro włączy się samo. Jeśli nie, „Sprawdź ponownie z konta” je wyszuka.", "Okno Konta i ekran powitalny wyjaśniają, że konto przenosi projekty, katalog i magazyn na każde urządzenie."] },
      es: { title: "Cuenta: te contamos qué te da", items: ["La pantalla Pro ahora dice: ¿ya pagaste? Inicia sesión con tu cuenta y Pro se activa solo. Si no ocurre, «Comprobar de nuevo desde la cuenta» lo busca.", "La ventana Cuenta y la pantalla de bienvenida explican que la cuenta trae proyectos, catálogo y stock a cada dispositivo."] }
    } },
    { v: "5.105.0", date: "2026-11-23", t: {
      en: { title: "Pro follows your account", items: ["Sign in with your e-mail and password (Account button) and, if you paid for Pro on ebanist.com with that same e-mail, Pro turns on by itself on that device: no code to copy.", "The e-mail must be confirmed. If you paid with another address, the code still works as before.", "On the Android app from Google Play, Pro is still decided only by Google Play."] },
      ro: { title: "Pro te urmează în cont", items: ["Te autentifici cu e-mail și parolă (butonul Cont) și, dacă ai plătit Pro pe ebanist.com cu aceeași adresă, Pro se activează singur pe acel dispozitiv: fără cod de copiat.", "Adresa trebuie să fie confirmată. Dacă ai plătit cu altă adresă, codul merge ca înainte.", "În aplicația Android din Google Play, Pro rămâne decis numai de Google Play."] },
      it: { title: "Il Pro ti segue con l'account", items: ["Accedi con e-mail e password (pulsante Account) e, se hai pagato il Pro su ebanist.com con la stessa e-mail, il Pro si attiva da solo su quel dispositivo: niente codice da copiare.", "L'e-mail deve essere confermata. Se hai pagato con un altro indirizzo, il codice funziona come prima.", "Nell'app Android di Google Play il Pro resta deciso solo da Google Play."] },
      fr: { title: "Le Pro vous suit avec votre compte", items: ["Connectez-vous avec votre e-mail et votre mot de passe (bouton Compte) et, si vous avez payé le Pro sur ebanist.com avec la même adresse, le Pro s'active tout seul sur cet appareil : plus de code à copier.", "L'adresse doit être confirmée. Si vous avez payé avec une autre adresse, le code fonctionne comme avant.", "Dans l'application Android de Google Play, le Pro reste décidé uniquement par Google Play."] },
      de: { title: "Pro folgt Ihrem Konto", items: ["Melden Sie sich mit E-Mail und Passwort an (Taste Konto): Wenn Sie Pro auf ebanist.com mit derselben Adresse bezahlt haben, schaltet sich Pro auf diesem Gerät von selbst ein, ohne Code zum Kopieren.", "Die E-Mail muss bestätigt sein. Haben Sie mit einer anderen Adresse bezahlt, funktioniert der Code wie bisher.", "In der Android-App aus Google Play entscheidet über Pro weiterhin nur Google Play."] },
      pl: { title: "Pro idzie za Twoim kontem", items: ["Zaloguj się e-mailem i hasłem (przycisk Konto), a jeśli za Pro zapłaciłeś na ebanist.com tym samym adresem, Pro włączy się samo na tym urządzeniu: bez kodu do kopiowania.", "Adres musi być potwierdzony. Jeśli płaciłeś innym adresem, kod działa jak dotąd.", "W aplikacji Android z Google Play o Pro nadal decyduje wyłącznie Google Play."] },
      es: { title: "Pro te sigue con tu cuenta", items: ["Inicia sesión con tu e-mail y contraseña (botón Cuenta) y, si pagaste Pro en ebanist.com con ese mismo e-mail, Pro se activa solo en ese dispositivo: sin código que copiar.", "El e-mail debe estar confirmado. Si pagaste con otra dirección, el código funciona como antes.", "En la app de Android de Google Play, Pro sigue decidiéndose solo por Google Play."] }
    } },
    { v: "5.104.0", date: "2026-11-23", t: {
      en: { title: "“What's new” page", items: ["This page: what changed in each update, in plain words.", "Open it from the **?** button, at the top of Help."] },
      ro: { title: "Pagina „Noutăți”", items: ["Pagina aceasta: ce s-a schimbat la fiecare actualizare, în cuvinte simple.", "O deschizi din butonul **?**, sus în Ajutor."] },
      it: { title: "Pagina «Novità»", items: ["Questa pagina: cosa cambia a ogni aggiornamento, in parole semplici.", "Si apre dal pulsante **?**, in cima alla Guida."] },
      fr: { title: "Page « Nouveautés »", items: ["Cette page : ce qui change à chaque mise à jour, en mots simples.", "Ouvrez-la depuis le bouton **?**, en haut de l'Aide."] },
      de: { title: "Seite „Neuigkeiten“", items: ["Diese Seite: was sich bei jedem Update ändert, in einfachen Worten.", "Sie öffnet sich über die Taste **?**, oben in der Hilfe."] },
      pl: { title: "Strona „Nowości”", items: ["Ta strona: co zmienia się przy każdej aktualizacji, prostymi słowami.", "Otworzysz ją przyciskiem **?**, na górze Pomocy."] },
      es: { title: "Página «Novedades»", items: ["Esta página: qué cambia en cada actualización, con palabras sencillas.", "Se abre desde el botón **?**, arriba en la Ayuda."] }
    } },
    { v: "5.103.0", date: "2026-11-23", t: {
      en: { title: "Open doors and drawers in Room 3D", items: ["The button is now inside the 3D room window and opens all doors and drawers at once.", "Units that collide are flagged, as before."] },
      ro: { title: "Deschide ușile și sertarele în „Camera în 3D”", items: ["Butonul e acum în fereastra camerei 3D și deschide deodată toate ușile și sertarele.", "Corpurile care se lovesc sunt semnalate, ca înainte."] },
      it: { title: "Apri ante e cassetti nella «Stanza in 3D»", items: ["Il pulsante ora è nella finestra della stanza 3D e apre tutte le ante e i cassetti insieme.", "I mobili che si urtano vengono segnalati, come prima."] },
      fr: { title: "Ouvrir portes et tiroirs dans la « Pièce en 3D »", items: ["Le bouton est maintenant dans la fenêtre de la pièce 3D et ouvre toutes les portes et tous les tiroirs d'un coup.", "Les meubles qui se heurtent sont signalés, comme avant."] },
      de: { title: "Türen und Schubladen im „Raum in 3D“ öffnen", items: ["Die Taste sitzt jetzt im 3D-Raumfenster und öffnet alle Türen und Schubladen auf einmal.", "Möbel, die sich berühren, werden wie bisher markiert."] },
      pl: { title: "Otwieranie drzwi i szuflad w „Pokoju w 3D”", items: ["Przycisk jest teraz w oknie pokoju 3D i otwiera naraz wszystkie drzwi i szuflady.", "Szafki, które na siebie wchodzą, są oznaczane jak dotąd."] },
      es: { title: "Abrir puertas y cajones en la «Habitación en 3D»", items: ["El botón ahora está en la ventana de la habitación 3D y abre todas las puertas y cajones a la vez.", "Los muebles que chocan se señalan, como antes."] }
    } },
    { v: "5.102.0", date: "2026-11-23", t: {
      en: { title: "Handles and real part shapes in Room 3D", items: ["Bar handles now appear on doors and drawers, in the finish from the catalog (brass/gold, stainless, black).", "Parts with a free contour (shelves with rounded corners, panels) are drawn in their exact shape.", "LED strip under the unit, on the plinth face (only with a plinth)."] },
      ro: { title: "Mânere și forma reală a pieselor în „Camera în 3D”", items: ["Mânerele bară apar pe uși și pe sertare, în finisajul din catalog (alamă/auriu, inox, negru).", "Piesele cu contur liber (rafturi cu colț rotunjit, panouri) se desenează cu forma lor exactă.", "Bandă LED sub corp, pe fața soclului (numai cu soclu)."] },
      it: { title: "Maniglie e forma reale dei pezzi nella «Stanza in 3D»", items: ["Le maniglie a barra compaiono su ante e cassetti, nella finitura del catalogo (ottone/oro, inox, nero).", "I pezzi con contorno libero (ripiani con angolo arrotondato, pannelli) sono disegnati con la loro forma esatta.", "Striscia LED sotto il mobile, sulla faccia dello zoccolo (solo con zoccolo)."] },
      fr: { title: "Poignées et forme réelle des pièces dans la « Pièce en 3D »", items: ["Les poignées barre apparaissent sur les portes et les tiroirs, dans la finition du catalogue (laiton/or, inox, noir).", "Les pièces à contour libre (étagères à angle arrondi, panneaux) sont dessinées avec leur forme exacte.", "Bandeau LED sous le meuble, sur la face du socle (uniquement avec socle)."] },
      de: { title: "Griffe und echte Teileform im „Raum in 3D“", items: ["Stangengriffe erscheinen auf Türen und Schubladen, in der Oberfläche aus dem Katalog (Messing/Gold, Edelstahl, Schwarz).", "Teile mit freier Kontur (Regalböden mit runder Ecke, Platten) werden in ihrer genauen Form gezeichnet.", "LED-Streifen unter dem Korpus, auf der Sockelblende (nur mit Sockel)."] },
      pl: { title: "Uchwyty i prawdziwy kształt części w „Pokoju w 3D”", items: ["Uchwyty prętowe pojawiają się na drzwiach i szufladach, w wykończeniu z katalogu (mosiądz/złoto, inox, czarny).", "Części o dowolnym konturze (półki z zaokrąglonym rogiem, panele) rysowane są w swoim dokładnym kształcie.", "Taśma LED pod korpusem, na froncie cokołu (tylko z cokołem)."] },
      es: { title: "Tiradores y forma real de las piezas en la «Habitación en 3D»", items: ["Los tiradores de barra aparecen en puertas y cajones, con el acabado del catálogo (latón/oro, inox, negro).", "Las piezas con contorno libre (baldas con esquina redondeada, paneles) se dibujan con su forma exacta.", "Tira LED bajo el mueble, en la cara del zócalo (solo con zócalo)."] }
    } },
    { v: "5.101.0", date: "2026-11-23", t: {
      en: { title: "LED strips, handle-less doors, gold handles, mirror", items: ["Vertical LED strip on the left or right side of a unit, with the light shown in Room 3D.", "Doors without a handle (push-to-open); the other doors of the unit keep theirs.", "Two brass/gold bar handles (192 and 384 mm), generic, marked as estimates.", "Silvered mirror, 4 mm, as a material."] },
      ro: { title: "Benzi LED, uși fără mâner, mânere aurii, oglindă", items: ["Bandă LED verticală pe lateralul stâng sau drept al unui corp, cu lumina văzută în „Camera în 3D”.", "Uși fără mâner (cu apăsare); celelalte uși ale corpului își păstrează mânerul.", "Două mânere bară alamă/auriu (192 și 384 mm), generice, marcate ca estimare.", "Oglindă argintată de 4 mm, ca material."] },
      it: { title: "Strisce LED, ante senza maniglia, maniglie dorate, specchio", items: ["Striscia LED verticale sul fianco sinistro o destro del mobile, con la luce visibile nella «Stanza in 3D».", "Ante senza maniglia (a pressione); le altre ante del mobile mantengono la loro.", "Due maniglie a barra ottone/oro (192 e 384 mm), generiche, segnate come stima.", "Specchio argentato da 4 mm, come materiale."] },
      fr: { title: "Bandeaux LED, portes sans poignée, poignées dorées, miroir", items: ["Bandeau LED vertical sur le côté gauche ou droit d'un meuble, avec la lumière visible dans la « Pièce en 3D ».", "Portes sans poignée (à pression) ; les autres portes du meuble gardent la leur.", "Deux poignées barre laiton/or (192 et 384 mm), génériques, marquées comme estimation.", "Miroir argenté de 4 mm, comme matériau."] },
      de: { title: "LED-Streifen, Türen ohne Griff, goldene Griffe, Spiegel", items: ["Senkrechter LED-Streifen an der linken oder rechten Seite eines Korpus, das Licht ist im „Raum in 3D“ zu sehen.", "Türen ohne Griff (Push-to-open); die anderen Türen des Korpus behalten ihren.", "Zwei Stangengriffe Messing/Gold (192 und 384 mm), allgemein, als Schätzung gekennzeichnet.", "Silberspiegel, 4 mm, als Material."] },
      pl: { title: "Taśmy LED, drzwi bez uchwytu, złote uchwyty, lustro", items: ["Pionowa taśma LED na lewym lub prawym boku korpusu, ze światłem widocznym w „Pokoju w 3D”.", "Drzwi bez uchwytu (push-to-open); pozostałe drzwi korpusu zachowują swój.", "Dwa uchwyty prętowe mosiądz/złoto (192 i 384 mm), ogólne, oznaczone jako szacunek.", "Lustro srebrzone 4 mm jako materiał."] },
      es: { title: "Tiras LED, puertas sin tirador, tiradores dorados, espejo", items: ["Tira LED vertical en el lateral izquierdo o derecho de un mueble, con la luz visible en la «Habitación en 3D».", "Puertas sin tirador (con pulsación); las demás puertas del mueble conservan el suyo.", "Dos tiradores de barra latón/oro (192 y 384 mm), genéricos, marcados como estimación.", "Espejo plateado de 4 mm, como material."] }
    } },
    { v: "5.99.0", date: "2026-11-22", t: {
      en: { title: "One free sample document", items: ["Without Pro you can print one document of your choice, once per device, with a “free version” watermark. After that, Pro is offered.", "CSV, JPG, STL, DXF, packages and sending stay Pro."] },
      ro: { title: "Un document de probă gratuit", items: ["Fără Pro poți tipări o singură dată, pe dispozitiv, un document la alegere, cu filigranul „versiune gratuită”. După aceea se oferă Pro.", "CSV, JPG, STL, DXF, pachetele și trimiterile rămân Pro."] },
      it: { title: "Un documento di prova gratuito", items: ["Senza Pro puoi stampare una sola volta, per dispositivo, un documento a scelta, con la filigrana «versione gratuita». Poi ti viene proposto Pro.", "CSV, JPG, STL, DXF, pacchetti e invii restano Pro."] },
      fr: { title: "Un document d'essai gratuit", items: ["Sans Pro, vous pouvez imprimer une seule fois par appareil un document de votre choix, avec le filigrane « version gratuite ». Ensuite, Pro vous est proposé.", "CSV, JPG, STL, DXF, packs et envois restent Pro."] },
      de: { title: "Ein kostenloses Probedokument", items: ["Ohne Pro können Sie einmal pro Gerät ein Dokument Ihrer Wahl mit dem Wasserzeichen „Gratisversion“ drucken. Danach wird Pro angeboten.", "CSV, JPG, STL, DXF, Pakete und Versand bleiben Pro."] },
      pl: { title: "Jeden darmowy dokument próbny", items: ["Bez Pro możesz raz na urządzeniu wydrukować jeden dokument do wyboru ze znakiem wodnym „wersja bezpłatna”. Potem zaproponujemy Pro.", "CSV, JPG, STL, DXF, paczki i wysyłka pozostają w Pro."] },
      es: { title: "Un documento de prueba gratis", items: ["Sin Pro puedes imprimir una sola vez por dispositivo un documento a tu elección, con la marca de agua «versión gratuita». Después se ofrece Pro.", "CSV, JPG, STL, DXF, paquetes y envíos siguen siendo Pro."] }
    } },
    { v: "5.98.3", date: "2026-11-22", t: {
      en: { title: "Parts list grouped by function", items: ["With 8 or more parts, the parts list in the Builder has headings: Body, Shelves and dividers, Doors and fronts, Drawers, Other, each with its count.", "Display only: cutting list, drilling, 3D and exports do not change."] },
      ro: { title: "Lista pieselor, grupată pe funcție", items: ["Cu 8 piese sau mai multe, lista de piese din Constructor are antete: Corp, Rafturi și despărțitori, Uși și fronturi, Sertare, Altele, fiecare cu numărul pieselor.", "Numai afișare: distinta, găurirea, 3D-ul și exporturile nu se schimbă."] },
      it: { title: "Elenco pezzi raggruppato per funzione", items: ["Con 8 pezzi o più, l'elenco pezzi nel Costruttore ha delle intestazioni: Corpo, Ripiani e divisori, Ante e frontali, Cassetti, Altro, ognuna con il numero dei pezzi.", "Solo visualizzazione: distinta, foratura, 3D ed esportazioni non cambiano."] },
      fr: { title: "Liste des pièces groupée par fonction", items: ["À partir de 8 pièces, la liste des pièces du Constructeur a des intitulés : Caisson, Étagères et séparations, Portes et façades, Tiroirs, Autres, chacun avec son nombre de pièces.", "Affichage seulement : nomenclature, perçage, 3D et exports ne changent pas."] },
      de: { title: "Teileliste nach Funktion gruppiert", items: ["Ab 8 Teilen hat die Teileliste im Konstruktor Überschriften: Korpus, Böden und Trennwände, Türen und Fronten, Schubladen, Sonstiges, jeweils mit der Teileanzahl.", "Nur Anzeige: Stückliste, Bohrungen, 3D und Exporte bleiben unverändert."] },
      pl: { title: "Lista części pogrupowana według funkcji", items: ["Przy 8 częściach lub więcej lista części w Konstruktorze ma nagłówki: Korpus, Półki i przegrody, Drzwi i fronty, Szuflady, Inne, każdy z liczbą części.", "Tylko wyświetlanie: rozkrój, wiercenia, 3D i eksporty się nie zmieniają."] },
      es: { title: "Lista de piezas agrupada por función", items: ["Con 8 piezas o más, la lista de piezas del Constructor tiene encabezados: Cuerpo, Baldas y divisiones, Puertas y frentes, Cajones, Otros, cada uno con su número de piezas.", "Solo visualización: despiece, taladros, 3D y exportaciones no cambian."] }
    } },
    { v: "5.97.0", date: "2026-11-20", t: {
      en: { title: "Client mode: photos, whole room, extras, send the proposal", items: ["Photos on any material or hardware item, shown to the client.", "New 3D button: “In your room” (with a survey) or “Whole composition”.", "Extras with a separate price: LED, one more shelf, one more drawer.", "“Send proposal” makes a JPG image and opens the phone's share sheet. It is a proposal, not a signed offer."] },
      ro: { title: "Modul Client: poze, camera întreagă, extra, propunerea trimisă", items: ["Poze pe orice material sau articol de feronerie, arătate clientului.", "Buton nou în 3D: „În camera ta” (cu releveu) sau „Toată compoziția”.", "Extra cu preț separat: LED, un raft în plus, un sertar în plus.", "„Trimite propunerea” face o imagine JPG și deschide foaia de partajare a telefonului. E o propunere, nu o ofertă semnată."] },
      it: { title: "Modalità Cliente: foto, stanza intera, extra, proposta inviata", items: ["Foto su qualsiasi materiale o articolo di ferramenta, mostrate al cliente.", "Nuovo pulsante 3D: «Nella tua stanza» (con rilievo) o «Intera composizione».", "Extra con prezzo separato: LED, un ripiano in più, un cassetto in più.", "«Invia la proposta» crea un'immagine JPG e apre il foglio di condivisione del telefono. È una proposta, non un'offerta firmata."] },
      fr: { title: "Mode Client : photos, pièce entière, extras, proposition envoyée", items: ["Photos sur n'importe quel matériau ou article de quincaillerie, montrées au client.", "Nouveau bouton 3D : « Dans votre pièce » (avec relevé) ou « Composition entière ».", "Extras avec prix séparé : LED, une étagère en plus, un tiroir en plus.", "« Envoyer la proposition » crée une image JPG et ouvre la feuille de partage du téléphone. C'est une proposition, pas une offre signée."] },
      de: { title: "Kundenmodus: Fotos, ganzer Raum, Extras, Angebot senden", items: ["Fotos zu jedem Material und jedem Beschlagartikel, dem Kunden gezeigt.", "Neue 3D-Taste: „In Ihrem Raum“ (mit Aufmaß) oder „Ganze Komposition“.", "Extras mit eigenem Preis: LED, ein Boden mehr, eine Schublade mehr.", "„Vorschlag senden“ erstellt ein JPG-Bild und öffnet das Teilen-Menü des Telefons. Es ist ein Vorschlag, kein unterschriebenes Angebot."] },
      pl: { title: "Tryb Klienta: zdjęcia, cały pokój, dodatki, wysłanie propozycji", items: ["Zdjęcia przy każdym materiale i elemencie okuć, pokazywane klientowi.", "Nowy przycisk 3D: „W Twoim pokoju” (z pomiarem) lub „Cała kompozycja”.", "Dodatki z osobną ceną: LED, jedna półka więcej, jedna szuflada więcej.", "„Wyślij propozycję” tworzy obraz JPG i otwiera menu udostępniania telefonu. To propozycja, a nie podpisana oferta."] },
      es: { title: "Modo Cliente: fotos, habitación entera, extras, propuesta enviada", items: ["Fotos en cualquier material o artículo de herrajes, mostradas al cliente.", "Nuevo botón 3D: «En tu habitación» (con medición) o «Toda la composición».", "Extras con precio aparte: LED, una balda más, un cajón más.", "«Enviar la propuesta» crea una imagen JPG y abre el menú de compartir del teléfono. Es una propuesta, no una oferta firmada."] }
    } },
    { v: "5.96.0", date: "2026-11-20", t: {
      en: { title: "Client mode: the client also chooses the hardware", items: ["Hinges, drawer slides and handles, by brand and name, without article codes. Only options that do not move any dimension are offered.", "The price is recalculated, and the choice appears in the signing window and on the offer PDF."] },
      ro: { title: "Modul Client: clientul alege și feroneria", items: ["Balamale, glisiere de sertare și mânere, cu marcă și nume, fără coduri de articol. Se oferă numai ce nu mută nicio cotă.", "Prețul se recalculează, iar alegerea apare în fereastra de semnare și pe PDF-ul ofertei."] },
      it: { title: "Modalità Cliente: il cliente sceglie anche la ferramenta", items: ["Cerniere, guide dei cassetti e maniglie, con marca e nome, senza codici articolo. Si offre solo ciò che non sposta nessuna quota.", "Il prezzo si ricalcola e la scelta compare nella finestra di firma e nel PDF dell'offerta."] },
      fr: { title: "Mode Client : le client choisit aussi la quincaillerie", items: ["Charnières, coulisses de tiroirs et poignées, avec marque et nom, sans codes d'article. Seules les options qui ne déplacent aucune cote sont proposées.", "Le prix est recalculé, et le choix apparaît dans la fenêtre de signature et sur le PDF de l'offre."] },
      de: { title: "Kundenmodus: der Kunde wählt auch die Beschläge", items: ["Scharniere, Schubladenführungen und Griffe, mit Marke und Name, ohne Artikelnummern. Angeboten wird nur, was kein Maß verschiebt.", "Der Preis wird neu berechnet, und die Auswahl erscheint im Unterschriftsfenster und im Angebots-PDF."] },
      pl: { title: "Tryb Klienta: klient wybiera też okucia", items: ["Zawiasy, prowadnice szuflad i uchwyty, z marką i nazwą, bez kodów artykułów. Oferowane jest tylko to, co nie przesuwa żadnego wymiaru.", "Cena jest przeliczana, a wybór widać w oknie podpisu i w PDF oferty."] },
      es: { title: "Modo Cliente: el cliente elige también los herrajes", items: ["Bisagras, guías de cajón y tiradores, con marca y nombre, sin códigos de artículo. Solo se ofrece lo que no mueve ninguna cota.", "El precio se recalcula, y la elección aparece en la ventana de firma y en el PDF de la oferta."] }
    } },
    { v: "5.95.0", date: "2026-11-20", t: {
      en: { title: "Client mode: a presentation with graphics", items: ["Proposal header, 3D on a warm background, and width / height / depth in three cards.", "“How it looks”: a front diagram in the chosen finishes (indicative); “What's included”; “What's next”, without promised dates.", "The price counts from the old figure to the new one."] },
      ro: { title: "Modul Client: prezentare cu grafică", items: ["Antet de propunere, 3D pe fundal cald, lățime / înălțime / adâncime în trei carduri.", "„Cum arată”: schemă a frontului cu finisajele alese (orientativă); „Ce include”; „Ce urmează”, fără termene promise.", "Prețul se numără de la cifra veche la cea nouă."] },
      it: { title: "Modalità Cliente: una presentazione con grafica", items: ["Intestazione di proposta, 3D su sfondo caldo, larghezza / altezza / profondità in tre schede.", "«Come appare»: schema del fronte con le finiture scelte (indicativa); «Cosa include»; «Cosa segue», senza tempi promessi.", "Il prezzo scorre dalla cifra vecchia a quella nuova."] },
      fr: { title: "Mode Client : une présentation avec graphiques", items: ["En-tête de proposition, 3D sur fond chaud, largeur / hauteur / profondeur en trois cartes.", "« Aspect » : schéma de la façade avec les finitions choisies (indicatif) ; « Ce qui est inclus » ; « Et ensuite », sans délais promis.", "Le prix défile de l'ancien chiffre au nouveau."] },
      de: { title: "Kundenmodus: eine Präsentation mit Grafik", items: ["Angebotskopf, 3D auf warmem Hintergrund, Breite / Höhe / Tiefe in drei Karten.", "„So sieht es aus“: Frontschema in den gewählten Oberflächen (unverbindlich); „Was enthalten ist“; „Wie es weitergeht“, ohne versprochene Termine.", "Der Preis zählt von der alten zur neuen Zahl."] },
      pl: { title: "Tryb Klienta: prezentacja z grafiką", items: ["Nagłówek propozycji, 3D na ciepłym tle, szerokość / wysokość / głębokość w trzech kartach.", "„Jak to wygląda”: schemat frontu w wybranych wykończeniach (orientacyjny); „Co zawiera”; „Co dalej”, bez obiecanych terminów.", "Cena przelicza się od starej liczby do nowej."] },
      es: { title: "Modo Cliente: una presentación con gráficos", items: ["Encabezado de propuesta, 3D sobre fondo cálido, ancho / alto / fondo en tres tarjetas.", "«Cómo se ve»: esquema del frente con los acabados elegidos (orientativo); «Qué incluye»; «Qué sigue», sin plazos prometidos.", "El precio cuenta desde la cifra anterior hasta la nueva."] }
    } }
  ];

  function lang(l) { return LANGS.indexOf(l) >= 0 ? l : "en"; }
  function ui(l) { return UI[lang(l)]; }
  function tx(rel, l) { return rel.t[lang(l)]; }
  function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }
  /* `**x**` → <b>x</b>; nimic altceva nu e markup (ca în ebanist-help.js) */
  function md(s) { return esc(s).replace(/\*\*(.+?)\*\*/g, "<b>$1</b>"); }
  function plain(s) { return String(s).replace(/\*\*/g, ""); }
  function fmtDate(iso, l) {
    try {
      var p = iso.split("-"), d = new Date(Date.UTC(+p[0], +p[1] - 1, +p[2]));
      return d.toLocaleDateString(lang(l), { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" });
    } catch (e) { return iso; }
  }

  /* HTML-ul foii; prima versiune e deschisă. Linkul spre blog: /<limbă>/blog/ (en: /blog/). */
  function render(l) {
    var U = ui(l), h = "";
    for (var i = 0; i < RELEASES.length; i++) {
      var r = RELEASES[i], c = tx(r, l);
      h += '<details class="hp-item wn-item"' + (i === 0 ? " open" : "") + "><summary><span>" + esc(plain(c.title)) +
        '<small class="wn-ver">' + esc(U.version) + " " + esc(r.v) + " · " + esc(fmtDate(r.date, l)) + "</small></span></summary>" +
        '<div class="hp-in"><ul class="wn-list">';
      for (var j = 0; j < c.items.length; j++) h += "<li>" + md(c.items[j]) + "</li>";
      h += "</ul></div></details>";
    }
    var base = "/" + (lang(l) === "en" ? "" : lang(l) + "/") + "blog/";
    h += '<p class="mini hp-foot">' + esc(U.older) + ' <a href="' + base + '" target="_blank" rel="noopener">' + esc(U.blog) + " ↗</a></p>";
    return h;
  }

  var API = { LANGS: LANGS, UI: UI, RELEASES: RELEASES, ui: ui, tx: tx, esc: esc, md: md, plain: plain, fmtDate: fmtDate, render: render };
  global.EBWhatsNew = API;
  if (typeof module !== "undefined" && module.exports) module.exports = API;
})(typeof window !== "undefined" ? window : globalThis);
